8	import {
9	  buildEditorFromExtensions,
10	  configExtension,
11	  getExtensionDependencyFromEditor,
12	  NestedEditorExtension,
13	} from '@lexical/extension';
14	import {describe, expect, test} from 'vitest';
15	
16	describe('NestedEditorExtension', () => {
17	  test('it sets _parentEditor implicitly', () => {
18	    using editor = buildEditorFromExtensions({name: 'parent'});
19	    const childEditor = editor.read(() =>
20	      buildEditorFromExtensions({
21	        dependencies: [NestedEditorExtension],
22	        name: 'child',
23	      }),
24	    );
25	    expect(childEditor._parentEditor).toBe(editor);
26	  });
27	  test('$getParentEditor can be overridden', () => {
28	    using editor = buildEditorFromExtensions({name: 'parent'});
29	    const childEditor = buildEditorFromExtensions({
30	      dependencies: [
31	        configExtension(NestedEditorExtension, {
32	          $getParentEditor: () => editor,
33	        }),
34	      ],
35	      name: 'child',
36	    });
37	    expect(childEditor._parentEditor).toBe(editor);
38	  });
39	  test('The theme is inherited by default', () => {
40	    const editor = buildEditorFromExtensions({
41	      name: 'parent',
42	      theme: {text: {bold: 'bold'}},
43	    });
44	    const childEditor = editor.read(() =>
45	      buildEditorFromExtensions({
46	        dependencies: [NestedEditorExtension],
47	        name: 'child',
48	      }),
49	    );
50	    expect(childEditor._config.theme.text?.bold).toBe('bold');
51	  });
52	  test('If the child has a theme it is not inherited', () => {
53	    using editor = buildEditorFromExtensions({
54	      name: 'parent',
55	      theme: {text: {bold: 'bold', italic: 'italic'}},
56	    });
57	    const childEditor = editor.read(() =>
58	      buildEditorFromExtensions({
59	        dependencies: [NestedEditorExtension],
60	        name: 'child',
61	        theme: {text: {italic: 'child-italic'}},
62	      }),
63	    );
64	    expect(childEditor._config.theme.text?.bold).toBe(undefined);
65	    expect(childEditor._config.theme.text?.italic).toBe('child-italic');
66	  });
67	  test('inheritEditableFromParent defaults false but can be enabled later', () => {
68	    using editor = buildEditorFromExtensions({
69	      name: 'parent',
70	    });
71	    const childEditor = editor.read(() =>
72	      buildEditorFromExtensions({
73	        dependencies: [NestedEditorExtension],
74	        editable: false,
75	        name: 'child',
76	      }),
77	    );
78	    expect(editor.isEditable()).toBe(true);
79	    expect(childEditor.isEditable()).toBe(false);
80	    getExtensionDependencyFromEditor(
81	      childEditor,
82	      NestedEditorExtension,
83	    ).output.inheritEditableFromParent.value = true;
84	    expect(childEditor.isEditable()).toBe(true);
85	    editor.setEditable(false);
86	    expect(editor.isEditable()).toBe(false);
87	    expect(childEditor.isEditable()).toBe(false);
88	  });
89	  test('inheritEditableFromParent works when configured true', () => {
90	    using editor = buildEditorFromExtensions({
91	      editable: false,
92	      name: 'parent',
93	    });
94	    const childEditor = editor.read(() =>
95	      buildEditorFromExtensions({
96	        dependencies: [
97	          configExtension(NestedEditorExtension, {
98	            inheritEditableFromParent: true,
99	          }),
100	        ],
101	        editable: false,
102	        name: 'child',
103	      }),
104	    );
105	    expect(editor.isEditable()).toBe(false);
106	    expect(childEditor.isEditable()).toBe(false);
107	    editor.setEditable(true);
108	    expect(editor.isEditable()).toBe(true);
109	    expect(childEditor.isEditable()).toBe(true);
110	  });
111	});
