782	export function triggerCommandListeners<
783	  TCommand extends LexicalCommand<unknown>,
784	>(
785	  editor: LexicalEditor,
786	  type: TCommand,
787	  payload: CommandPayloadType<TCommand>,
788	): boolean {
789	  const editors = getEditorsToPropagate(editor);
790	
791	  for (let i = 4; i >= 0; i--) {
792	    for (let e = 0; e < editors.length; e++) {
793	      const currentEditor = editors[e];
794	      const commandListeners = currentEditor._commands;
795	      const listenerInPriorityOrder = commandListeners.get(type);
796	
797	      if (listenerInPriorityOrder !== undefined) {
798	        const listenersSet = listenerInPriorityOrder[i];
799	
800	        if (listenersSet !== undefined) {
801	          const listeners = Array.from(listenersSet);
802	          const listenersLength = listeners.length;
803	
804	          let returnVal = false;
805	          updateEditorSync(currentEditor, () => {
806	            for (let j = 0; j < listenersLength; j++) {
807	              if (listeners[j](payload, editor)) {
808	                returnVal = true;
809	                return;
810	              }
811	            }
812	          });
813	          if (returnVal) {
814	            return returnVal;
815	          }
816	        }
817	      }
818	    }
819	  }
820	
821	  return false;
822	}
823	
824	function $triggerEnqueuedUpdates(editor: LexicalEditor): void {
825	  const queuedUpdates = editor._updates;
826	
827	  if (queuedUpdates.length !== 0) {
828	    const queuedUpdate = queuedUpdates.shift();
829	    if (queuedUpdate) {
830	      const [updateFn, options] = queuedUpdate;
831	      $beginUpdate(editor, updateFn, options);
832	    }
833	  }
834	}
835	
836	function triggerDeferredUpdateCallbacks(
837	  editor: LexicalEditor,
838	  deferred: Array<() => void>,
839	): void {
840	  editor._deferred = [];
841	
842	  if (deferred.length !== 0) {
843	    const previouslyUpdating = editor._updating;
844	    editor._updating = true;
845	
846	    try {
847	      for (let i = 0; i < deferred.length; i++) {
848	        deferred[i]();
849	      }
850	    } finally {
851	      editor._updating = previouslyUpdating;
852	    }
853	  }
854	}
855	
856	function $processNestedUpdates(
857	  editor: LexicalEditor,
858	  initialSkipTransforms?: boolean,
859	): boolean {
860	  const queuedUpdates = editor._updates;
861	  let skipTransforms = initialSkipTransforms || false;
862	
863	  // Updates might grow as we process them, we so we'll need
864	  // to handle each update as we go until the updates array is
865	  // empty.
866	  while (queuedUpdates.length !== 0) {
867	    const queuedUpdate = queuedUpdates.shift();
868	    if (queuedUpdate) {
869	      const [nextUpdateFn, options] = queuedUpdate;
870	      const pendingEditorState = editor._pendingEditorState;
871	
872	      let onUpdate;
873	
874	      if (options !== undefined) {
875	        onUpdate = options.onUpdate;
876	
877	        if (options.skipTransforms) {
878	          skipTransforms = true;
879	        }
880	        if (options.discrete) {
881	          invariant(
882	            pendingEditorState !== null,
883	            'Unexpected empty pending editor state on discrete nested update',
884	          );
885	          pendingEditorState._flushSync = true;
886	        }
887	
888	        if (onUpdate) {
889	          editor._deferred.push(onUpdate);
890	        }
891	
892	        addTags(editor, options.tag);
893	      }
894	
895	      if (pendingEditorState == null) {
896	        $beginUpdate(editor, nextUpdateFn, options);
897	      } else {
898	        nextUpdateFn();
899	      }
