/**
 * Run the command listeners registered on each editor in `editors`, in
 * descending priority order, passing `dispatchEditor` as the editor argument to
 * each listener (so that it reflects the editor that originally dispatched the
 * command). Each editor's listeners run within an update for that editor, so
 * `$getEditor()` inside a listener returns the editor that owns it rather than
 * `dispatchEditor`.
 *
 * This is the shared machinery behind {@link triggerCommandListeners} and is
 * used by NestedEditorExtension to propagate commands from a child editor to a
 * parent editor (possibly after deferring past an in-progress parent update).
 */
export function triggerCommandListenersForEditors<
  TCommand extends LexicalCommand<unknown>,
>(
  editors: Array<LexicalEditor>,
  dispatchEditor: LexicalEditor,
  type: TCommand,
  payload: CommandPayloadType<TCommand>,
): boolean {
  for (let i = 4; i >= 0; i--) {
    for (let e = 0; e < editors.length; e++) {
      const currentEditor = editors[e];
      const commandListeners = currentEditor._commands;
      const listenerInPriorityOrder = commandListeners.get(type);

      if (listenerInPriorityOrder !== undefined) {
        const listenersSet = listenerInPriorityOrder[i];

        if (listenersSet !== undefined) {
          const listeners = Array.from(listenersSet);
          const listenersLength = listeners.length;

          let returnVal = false;
          updateEditorSync(currentEditor, () => {
            for (let j = 0; j < listenersLength; j++) {
              if (listeners[j](payload, dispatchEditor)) {
                returnVal = true;
                return;
              }
            }
          });
          if (returnVal) {
            return returnVal;
          }
        }
      }
    }
  }

  return false;
