  const originalDispatchCommand = editor.dispatchCommand;
  function dispatchCommand<TCommand extends LexicalCommand<unknown>>(
    this: LexicalEditor,
    type: TCommand,
    payload: CommandPayloadType<TCommand>,
  ): boolean {
    const parentEditor = editor._parentEditor;
