import {
  $getEditor,
  type CommandPayloadType,
  defineExtension,
  type LexicalCommand,
  LexicalEditor,
  safeCast,
  triggerCommandListenersForEditors,
} from 'lexical';

import {LexicalBuilder} from './LexicalBuilder';
import {namedSignals} from './namedSignals';
import {effect} from './signals';

export interface NestedEditorConfig {
  $getParentEditor: () => LexicalEditor;
  inheritEditableFromParent: boolean;
}

function $defaultGetParentEditor() {
  const editor = $getEditor();
  LexicalBuilder.fromEditor(editor);
  return editor;
}

/**
 * Override the child editor's dispatchCommand so that commands propagate to the
 * parent editor after the child's own command listeners have run.
 *
 * When the parent editor is not currently updating, propagation happens
 * synchronously and the return value reflects whether the parent handled the
 * command (this is the default behavior of a nested editor with a parentEditor).
 *
 * When the parent editor IS updating, propagating synchronously would force an
 * early commit of the parent's pending update, so instead the child's listeners
 * run synchronously (with dispatchCommand returning only the child-side result)
 * and the propagation to the parent is deferred until the parent's update
 * finishes, at which point the parent's command listeners run exactly once.
 */
function registerCommandPropagation(editor: LexicalEditor): () => void {
  const originalDispatchCommand = editor.dispatchCommand;
  function dispatchCommand<TCommand extends LexicalCommand<unknown>>(
    this: LexicalEditor,
    type: TCommand,
    payload: CommandPayloadType<TCommand>,
  ): boolean {
    const parentEditor = editor._parentEditor;
    if (parentEditor !== null && parentEditor._updating) {
      // Run the child's own command listeners now, but defer propagation to
      // the parent until its in-progress update has completed. Pushing onto
      // the parent's deferred queue guarantees the parent will commit and run
      // this callback exactly once after the update finishes.
      const result = triggerCommandListenersForEditors(
        [editor],
        editor,
        type,
        payload,
      );
