        triggerCommandListenersForEditors(
          [parentEditor],
          editor,
          type,
          payload,
        );
      });
      return result;
    }
    return originalDispatchCommand.call(editor, type, payload);
  }
  editor.dispatchCommand = dispatchCommand;
  return () => {
    if (editor.dispatchCommand === dispatchCommand) {
      editor.dispatchCommand = originalDispatchCommand;
    }
  };
}

export const NestedEditorExtension = defineExtension({
  build: (editor, config) =>
